  ["Vanessa "] = "Vanessa",
  ["A gas meter? It should... need to <P_Yellow>insert coins</> to work."] = "Um medidor de gás? Deveria... precisar <P_Yellow> inserir moedas </> para funcionar.",
  ["A gas meter? I have to insert a copper penny."] = "Um medidor de gás? Tenho que inserir uma moeda de cobre.",
  ["Valerie discovery path"] = "Caminho de descoberta de Valerie",
  ["Valerie"] = "Valéria",
