  ["Dock queuing route"] = "Rota de fila de doca",
  ["Dock atmosphere NPC 1"] = "Atmosfera da doca NPC 1",
  ["Dock atmosphere NPC 2"] = "Atmosfera de doca NPC 2",
  ["Dock atmosphere NPC 3"] = "Atmosfera de doca NPC 3",
